params.blog_listing_source:
{% require_css position="header" %}
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/slick-carousel/1.9.0/slick.min.css" />
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/slick-carousel/1.9.0/slick-theme.min.css" />
<style type="text/css">
  /* 
  * =============================
  *     Blog Listing Template
  * =============================
  *  */

  .hs-blog-listing h1{
    color: #ce9e05;
    font-weight: 400;
    margin-bottom: 10px;
    font-size: 38px;
    line-height: 1.2;
  }

  .hs-blog-listing .split-hero-wrapper-all .split-hero-bottom h1 {
    font-family: "Helvetica Neue",Arial,sans-serif;
    color: #2b3640;
    font-weight: 700;
  }

  .hs-blog-listing h2 {
    color: #2b3640;
    margin-top: 20px;
    margin-bottom: 10px;
    font-size: 32px;
    line-height: 1.2;
    font-weight: 700;
  }

  .hs-blog-listing h3 {
    margin-top: 10px;
    margin-bottom: 5px;
    color: #ab333a;
    font-size: 22px;
    line-height: 1.2;
    text-decoration: none;
    text-transform: uppercase;
    color: #ce9e05;
    font-size: 22px;
    line-height: 1.3em;
    text-decoration: none;
    text-transform: uppercase;
  }

  .hs-blog-listing .listing_email_subscribe {
    background-color: #1E2B33;
    box-shadow: 0 0 5px 0 rgba(0,0,0,.1);
    padding: 15px;
    border-radius: 0;
  }

  .hs-blog-listing .listing_email_subscribe form div > label {
    display: none !important;
  }

  .hs-blog-listing .listing_email_subscribe p {
    font-size: 10px;
    line-height: 1.2;
    color: #fff;
    margin: 0;
    clear: both;
  }

  .hs-blog-listing .listing_email_subscribe h3 {
    color: #fff;
    font-size: 14px!important;
    font-weight: 600!important;
    margin-top: 0;
    text-transform: initial;
    margin-bottom: 10px!important;
  }

  .hs-blog-listing .listing_email_subscribe form div.hs_email {
    width: 60%;
    float: left;
    clear: initial;
    margin-bottom: 20px;
  }

  .hs-blog-listing .listing_email_subscribe form div.hs_submit {
    width: 40%;
    float: right;
    clear: initial;
    margin: 0;
  }

  .hs-blog-listing .listing_email_subscribe form div.hs_submit input {
    min-height: 46px;
    padding: 0px 10px !important;
    border-radius: 0;
    -webkit-transition: all 200ms ease;
    transition: all 200ms ease;
    line-height: 1.2em;
    border: 0;
    color: #fff;
    width: 100%;
    cursor: pointer;
    margin: 0;
    font-size: 13px;
    border: 2px solid #fff;
    background-color: transparent !important;
    font-weight: 400;
    text-align: center;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    border-top-right-radius: 0 !important;
    border-bottom-right-radius: 0 !important;
    min-width: 100%;
  }

  .hs-blog-listing .listing_email_subscribe form div.hs_email input {
    min-height: 46px;
    border-radius: 0;
    border-top-left-radius: 0 !important;
    border-bottom-left-radius: 0 !important;
    padding-left: 15px;
    font-size: 13px;
    line-height: 1.5;
    color: #333;
    vertical-align: middle;
    background-color: #fff;
    border: 1px solid #ccc;
    width: 100%;
  }

  .hs-blog-listing .listing_email_subscribe form > div ul.hs-error-msgs li label {
        color: #fff;
    font-size: 9px;
    margin: 0;
  }

  .hs-blog-listing .blog_post_main {
    padding-bottom: 70px;
  }

  .hs-blog-listing #blog_post_main .row-fluid-wrapper.row-depth-1.row-number-2 {
    max-width: 100% !important;
    padding: 0!important;
  }

  .hs-blog-listing .main_section_wrapper{
    padding: 60px 30px;
    background-color: transparent;
  }

  .hs-blog-listing .main_section {
    max-width: 1080px;
    margin-right: auto;
    margin-left: auto!important;
    padding: 0;
    position: relative;
  }

  .hs-blog-listing .main_section h1{
    color: #333;
    font-size: 38px;
    line-height: 44px;
    font-weight: 700;
    text-transform: unset;
    padding-bottom: 20px;
  }

  .hs-blog-listing .main_section .badge_img {
    position: absolute;
    left: 30px;
    top: 65px;
    z-index: 5000;
    display: block;
    width: 120px;
    margin-right: auto;
    -webkit-transform: translate(-10px, -10px);
    -ms-transform: translate(-10px, -10px);
    transform: translate(-10px, -10px);
  }

  .hs-blog-listing .main_section .heading_slider{
    float: left;
    width: 70%;
  }

  .hs-blog-listing .main_section .google_search{
    float: left;
    width: 30%;
    padding-left: 30px;
    padding-top: 12px;
  }

  .hs-blog-listing .main_section .google_search form label{
    display: none;
  }

  .hs-blog-listing .main_section .google_search form input[type="text"]{
    display: inline-block;
    width: 85%;
    max-width: 350px;
    margin-bottom: 0px;
    float: left;
    border: 1px solid #d6d6d6;
    border-radius: 3px;
    height: 38px;
    padding-left: 12px;
  }

  .hs-blog-listing .main_section .google_search form a.hs-button{
    width: 15%;
    float: left;
    background-color: transparent;
    background-image: url(https://cdn2.hubspot.net/hubfs/69769/adhere/musica-searcher-2.svg);
    background-position: 50% 50%;
    background-size: 20px;
    background-repeat: no-repeat;
    opacity: 1;
    -webkit-transition: all 200ms ease;
    -moz-transition: all 200ms ease;
    transition: all 200ms ease;
    text-indent: -999em;
    padding: 9px 15px;
    cursor: pointer;
  }

  .hs-blog-listing .custom_form_wrapper{
    width: 30%;
    margin-top: 5px;
    margin-bottom: 0px;
    padding-left: 30px;
    float: right;
  }

  .hs-blog-listing .custom_form_wrapper form input.search {
    width: 85%;
    margin-bottom: 0px;
    float: left;
    border-radius: 0;
    min-height: 45px;
    border: 1px solid #333;
    padding: 0 12px;
    font-size: 14px;
    line-height: 1.5;
    color: #333333;
    vertical-align: middle;
    background-color: #ffffff;
  }

  .hs-blog-listing .custom_form_wrapper form input.search_btn {
    width: 15%;
    height: 46px;
    float: left;
    background-color: transparent;
    background-image: url(https://cdn2.hubspot.net/hubfs/5463091/Images/search.svg);
    background-position: 50% 50%;
    background-size: 35px;
    background-repeat: no-repeat;
    opacity: 1;
    -webkit-transition: all 200ms ease;
    transition: all 200ms ease;
    display: inline-block;
    cursor: pointer;
    border: 0;
    padding: 0;
    margin: 0;
  }

  .hs-blog-listing ::placeholder { 
    color: #999;
    opacity: 1; 
  }

  .hs-blog-listing :-ms-input-placeholder { 
    color: #999;
  }

  .hs-blog-listing ::-ms-input-placeholder { 
    color: #999;
  }

  /*** Slider Section ***/


  /* Slick.js: Hide slider until content have loaded */
  .slider_post_wrapper {
    opacity: 0;
    visibility: hidden;
    transition: opacity 1s ease;
    -webkit-transition: opacity 1s ease;
  }

  .slider_post_wrapper.slick-initialized {
    visibility: visible;
    opacity: 1;    
  }

  .hs-blog-listing .slider_post_wrapper {
    width: 70%;
    float: left;
  }

  .hs-blog-listing .featured_img_wrapper {
    width: 60%;
    float: left;
    background-size: cover;
    background-position: 50% 50%;
    box-shadow: inset 0 0 3px 0 rgba(0, 0, 0, .15);
    min-height: 437px;
    position: relative;
  }

  .hs-blog-listing .featured_img_wrapper a {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
  }

  .hs-blog-listing .featured_body {
    width: 40%;
    float: right;
    position: relative;
    cursor: pointer;
    min-height: 437px;
  }

  .hs-blog-listing .featured_body p {
    -webkit-transition: all 200ms ease;
    -moz-transition: all 200ms ease;
    transition: all 200ms ease;  
  }

  .hs-blog-listing .featured_body:hover p{
    color: #ce9e05!important;
  }

  .hs-blog-listing .featured_body_inner {
    background-color: #fff;
    padding: 20px;
    border: 10px solid #D8D8D8;
    min-height: 437px;
    -webkit-transition: all 200ms ease;
    transition: all 200ms ease;
  }

  .hs-blog-listing .featured_posts:hover .featured_body_inner {
    border: 10px solid #0f4c81;
  }

  .hs-blog-listing #main_section .featured_body_inner p{
    color: #333 !important;
    font-size: 16px;
    line-height: 1.5;
    margin-bottom: 10px;
  }

  .hs-blog-listing #main_section .featured_body_inner .preview_text h1,
  .hs-blog-listing #main_section .featured_body_inner .preview_text h2,
  .hs-blog-listing #main_section .featured_body_inner .preview_text h3,
  .hs-blog-listing #main_section .featured_body_inner .preview_text h4{
    color: #000;
    font-size: 16px;
    line-height: 1.5em;
    margin-bottom: 10px;
    display: none;
  }

  .hs-blog-listing #main_section .featured_body_inner a.read_more{
    -webkit-transition: all 200ms ease;
    -moz-transition: all 200ms ease;
    transition: all 200ms ease;
    text-transform: uppercase;
    position: absolute;
    bottom: 24px;
    color: #0f4c81;
    font-weight: 700;
    letter-spacing: 0.05em;
    font-size: 14px;
    line-height: 1.5;
  }

  .hs-blog-listing #main_section .featured_body_inner a.read_more:hover{
    text-decoration: none;
    padding-left: 3px;
    color: #0f4c81;
  }

  .hs-blog-listing .slider_post_wrapper button.slick-prev{
    left: 0;
  }

  .hs-blog-listing .slider_post_wrapper button.slick-next {
    right: 41.2%;
  }

  .hs-blog-listing .slick-prev:before, 
  .hs-blog-listing .slick-next:before {
    font-family: "Font Awesome 5 Free" !important;
    font-weight: 900;
  }

  .hs-blog-listing .slick-prev:before {
    content: '\f104'!important;
  }

  .hs-blog-listing .slick-next:before {
    content: '\f105'!important;
  }

  .hs-blog-listing .slider_post_wrapper button.slick-arrow {
    width: 40px;
    height: 40px;
    margin-left: 10px;
    border: 1px solid #505050;
    border-radius: 200px;
    background-color: rgba(0, 0, 0, .5);
    color: silver;
    z-index: 1;
  }

  .hs-blog-listing .slider_post_wrapper ul.slick-dots {
    top: 28px;
    right: initial;
    left: 63.6%;
    width: auto;
    bottom: initial!important;
    padding: 0;
  }

  .hs-blog-listing .slider_post_wrapper .slick-dots li{
    width: 25px;
    height: 2px;
    margin: 0 4px;
    background-color: rgba(34,34,34,0.3);
  }

  .hs-blog-listing .slider_post_wrapper .slick-dots li button:before{
    display: none;
  }

  .hs-blog-listing .slider_post_wrapper .slick-dots li.slick-active{
    background-color: #7A7A7A;
  }

  .hs-blog-listing .main_section .slick-dotted.slick-slider{
    margin-bottom: 0;
  }

  /*** Sidebar CTA ***/

  .hs-blog-listing .blog_sidebar{
    width: 30%;
    float: right;
    padding-left: 30px;
  }

  .hs-blog-listing .sidebar_cta{
    margin-bottom: 26px;
    padding: 20px 20px;    
    min-height: 250px;
    background-position: 0px 0px, 50% 50%;
    background-size: auto, cover;
    background-repeat: repeat, no-repeat;
    text-align: center;
    display: table;
    border-radius: 0;
  }

  .hs-blog-listing .sidebar_cta .cta_body{

    display: table-cell;
    vertical-align: middle;
  }

  .hs-blog-listing .sidebar_cta h3{
    margin-top: 0;
    margin-bottom: 10px;
    font-size: 22px;
    line-height: 1.3em;
    font-weight: 700;
    color: #fff;
    text-transform: initial;
  }

  .hs-blog-listing .sidebar_cta p {
    margin-bottom: 20px;
    color: #fff;
    font-size: 18px;
    line-height: 1.3em;
    text-shadow: 1px 1px 1px rgba(0, 0, 0, .3);
  }

  .hs-blog-listing .sidebar_cta img{
    max-height: 40px;
    margin-top: 10px;
    margin-bottom: 25px;
    padding: 10px;
    background-color: #fff;
  }

  .hs-blog-listing .sidebar_cta .cta_button {
    display: inline-block !important; 
    font-weight: 400 !important;
    color: #fff !important;
    text-align: center !important;
    vertical-align: middle !important;
    -webkit-user-select: none !important;
    -moz-user-select: none !important;
    -ms-user-select: none !important;
    user-select: none !important;
    background-color: transparent !important;
    border: 2px solid #fff !important;
    padding: 15px 20px !important;
    font-size: 1rem !important;
    line-height: 1.5 !important;
    border-radius: 0 !important;
    -webkit-transition: all 200ms ease !important;
    -moz-transition: all 200ms ease !important;
    transition: all 200ms ease !important;
  }

  /*** Post Listing Section ***/

  .hs-blog-listing .main_listing{
    padding-bottom:50px;
  }

  .hs-blog-listing .main_listing.all-listing {
    padding-top: 50px;
  }

  .hs-blog-listing .main_listing.all-listing {
    padding-bottom: 70px;
  }

  .hs-blog-listing .main_listing_inner{
    margin-top: 0;
    max-width: 1080px;
    margin-right: auto;
    margin-left: auto;
    padding: 0;
  }

  .hs-blog-listing .all-listing .main_listing_inner {
    max-width: 850px;
  }

  /* Recent Posts */
  .hs-blog-listing .post_item{
    width: 33.33%;
    margin-right: 0;
    float: left;
    padding: 12px;
  }

  .hs-blog-listing .recent_posts_wrapper .post_item:nth-child(3n+3){
    margin-right: 0;
  }

  /* Blog All */
  .hs-blog-listing .post_item.post-item-all {
    width: 100%;
    margin-right: 0;
    float: none;
    padding: 15px 0;
    webkit-transition: all 200ms ease !important;
    transition: all 200ms ease !important;
    border-bottom: 1px solid rgba(0, 0, 0, 0.1);
  }

  .hs-blog-listing .post_item.post-item-all:first-child {
    padding-top: 0;
  }

  .hs-blog-listing .post_item.post-item-all:hover {
    padding-left: 30px;
  }

  .hs-blog-listing .recent_posts_wrapper .headting_title {  
    margin-bottom: 0;
    background-color: #272727;
    border-left: 4px solid #0f4c81;
    border-top-left-radius: 0;
    border-top-right-radius: 0;
  }

  .hs-blog-listing .all-listing .recent_posts_wrapper .headting_title {  
    display: none;
  }

  .hs-blog-listing .recent_posts_wrapper .headting_title p.recent_text {
    display: inline-block;
    margin: 18px 30px 18px 15px;
    padding-top: 2px;
    color: #fff;
    font-size: 14px;
    line-height: 1.2em;
    font-weight: 400;
    letter-spacing: 3px;
    text-transform: uppercase;
  }

  .hs-blog-listing .tag_section {
    float: right;
    position: relative;
  }

  .hs-blog-listing .tag_section .text{
    font-size: 14px;
    font-weight: 300;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #fff;
    line-height: 20px;
    padding: 18px 20px 16px 16px;
    -webkit-transition: all 200ms ease;
    transition: all 200ms ease;
    cursor: pointer;
    letter-spacing: 2px;
  }

  .hs-blog-listing .tag_section:hover .text,
  .hs-blog-listing .tag_section.active .text {
    background-color: #0f4c81;
    color: #fff;
  }

  .hs-blog-listing .tag_section .text i {
    font-weight: bold;
    font-size: 17px;
    display: inline-block;
    padding-left: 3px;
    position: relative;
    top: 1px;
  }

  .hs-blog-listing .tag_section ul {
    margin: 0;
    padding: 0;
    list-style: none;
    text-align: left;
    height: 240px;
    overflow-y: scroll;
    background: #f5f6f7;
    display: none;
    position: absolute;
    top: 54px;
    width: 100%;
    z-index: 5;
    left: 0;
  }

  .hs-blog-listing .tag_section ul.active {
    display: block;
  }

  .hs-blog-listing .tag_section ul li a {
    display: block;
    padding: 11px 20px;
    color: #222;
    text-decoration: none;
    text-transform: unset;
    font-size: 12px;
    font-weight: 400;
    letter-spacing: 1px;
    line-height: 1.6em;
  }

  .hs-blog-listing .tag_section ul li a:hover,
  .hs-blog-listing .tag_section ul li.active a{
    background-color: #fff;
    color: #263e79 !important;
  }

  .hs-blog-listing .url_slug{
    display: none;
  }

  .hs-blog-listing .post_listing{
    background-color: #f6f6f6;
    padding: 30px 6px 0 6px;
  }

  .hs-blog-listing .post_listing.post-listing-all {
    background-color: transparent;
    padding-top: 0;
  }

  .hs-blog-listing .list_featured_img {
    min-height: 250px;
    background-position: 50% 50%;
    background-size: cover;
    background-repeat: no-repeat;
    position: relative;
  }

  .hs-blog-listing .list_featured_img a {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    -webkit-transition: all 200ms ease;
    -moz-transition: all 200ms ease;
    transition: all 200ms ease;
  }

  .hs-blog-listing .list_featured_img a:hover{
    background-color: rgba(22, 131, 208, 0.5);
  }

  .hs-blog-listing .recent_posts_wrapper .list_featured_img_wrapper img {
    height: 250px;
    width: 100%;
    object-fit: cover;
  }

  .hs-blog-listing .list_featured_img_wrapper {
    background-color: #1E2B33;
  }

  .hs-blog-listing .list_featured_img_wrapper img {
    opacity: 1;
    -webkit-transition: opacity 200ms ease;
    -moz-transition: opacity 200ms ease;
    transition: opacity 200ms ease;
  }

  .hs-blog-listing .list_featured_img_wrapper img:hover{
    opacity: 0.5;
  }

  .hs-blog-listing .recent_posts_wrapper .post_item .list_post_body h2 {
    padding: 4px 0;
  }

  .hs-blog-listing .recent_posts_wrapper .post_item .list_post_body h2,
  .hs-blog-listing .recent_posts_wrapper .post_item .list_post_body h2 a {
    margin-top: 10px;
    margin-bottom: 5px;
    font-family: "Helvetica Neue",Arial,sans-serif;
    color: #2b3640;
    font-weight: 700;
    font-size: 18px;
    line-height: 1.4em;
    text-decoration: none;
    text-transform: initial;
    -webkit-transition: all 200ms ease;
    transition: all 200ms ease;
    text-decoration: none;
  }

  .hs-blog-listing .recent_posts_wrapper .post_item.post-item-all .list_post_body h2,
  .hs-blog-listing .recent_posts_wrapper .post_item.post-item-all .list_post_body h2 a {
    font-size: 32px;
  }

  .hs-blog-listing .recent_posts_wrapper .post_item:hover .list_post_body h2 a {
    text-decoration: none;
  }

  .hs-blog-listing .recent_posts_wrapper .post_item .list_post_body p,
  .hs-blog-listing .recent_posts_wrapper .post_item .list_post_body span {
    margin-bottom: 10px;
    position: relative;
    z-index: 10;
    color: #333 !important;
    font-size: 16px !important;
    line-height: 1.6em !important;
    -webkit-transition: all 200ms ease;
    transition: all 200ms ease;
  }

  .hs-blog-listing .list_post_body .post_tags{
    padding-top: 10px;
  }

  .hs-blog-listing .list_post_body .post_tags a {
    display: inline-block;
    margin-right: 5px;
    padding-right: 10px;
    padding-left: 10px;
    border: 1px solid #6c6c6c;
    border-radius: 4px;
    -webkit-transition: all 200ms ease;
    -moz-transition: all 200ms ease;
    transition: all 200ms ease;
    color: #6c6c6c;
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0px;
    text-decoration: none;
    text-transform: uppercase;
    line-height: 22px;
  }

  .hs-blog-listing .list_post_body .post_tags a:hover {
    border-color: #0f4c81;
    background-color: #0f4c81;
    color: #fff;
  }

  .hs-blog-listing .bottom_post_tags a {
    padding: 6px 10px;
    color: #666;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.5px;
    text-transform: unset;
    line-height: 1.6em;
  }

  .hs-blog-listing .recent_posts_wrapper .btn_section{
    text-align: center;
    padding-top: 19px;
  }

  .hs-blog-listing .recent_posts_wrapper .btn_sec{
    margin-right: 10px;
    margin-left: 10px;
    margin-top: 10px;
    margin-bottom: 10px;
    padding: 12px 20px;
    border: 2px solid transparent;
    border-radius: 4px;
    background-color: #1683d0;
    -webkit-transition: all 200ms ease;
    -moz-transition: all 200ms ease;
    transition: all 200ms ease;
    color: #fff;
    font-weight: 400;
    display: inline-block;
    line-height: inherit;
    text-align: center;
    letter-spacing: 1px;
    text-decoration: none;
    text-transform: uppercase;
    font-size: 15px;
    font-family: "Helvetica Neue",Arial,sans-serif !important;
  }

  .hs-blog-listing .recent_posts_wrapper .btn_sec:hover {
    color: #fff;
    opacity: 1;
    -webkit-transform: translate(0px, -3px);
    -ms-transform: translate(0px, -3px);
    transform: translate(0px, -3px);
  }

  .hs-blog-listing .btn_section .load_more_btn {
    margin-right: 0;
    background-color: #0f4c81;
    cursor: pointer;
  }

  .hs-blog-listing .recent_posts_wrapper .all_articles_btn {
    display: inline-block;
  }


  .hs-blog-listing .recent_posts_wrapper a.view-all {
    border: 2px solid #333;
    background-color: transparent;
    color: #333;
  }

