{% end_require_css %}

<div class="blog_listing_section">

  {% if blog_author %}

  <div class="split-hero-wrapper hs-author-profile">
    <div class="split-hero-top"></div>
    <div class="split-hero-bottom blog-author">
      {% if blog_author.avatar %}
      <div class="about-author-page-img" style="background-image:url({{ blog_author.avatar }});"></div>
      {% else %}
      <div class="about-author-page-img" style="background-color:gray;"></div>
      {% endif %}
      <div class="module-max650">
        <h3 class="name">{{ blog_author.display_name }}</h3>
        <div class="content">
          {{ blog_author.bio }}
        </div>
      </div>
    </div>
  </div>

  {% endif %}


  {% if request.full_url is not containing "/all" %}
    {% if !blog_author %}
    <div class="main_section_wrapper">
      <div class="main_section clearfix" id="main_section">
        <div class="heading_google_search clearfix">

          {% if group.public_title %}
          <div class="heading_slider">
            <h1>
              {{ group.public_title }}
            </h1>
          </div>
          {% else %}
          <div class="heading_slider">
            <h1>{{ content.name }}</h1>
          </div> 
          {% endif %}

          <!-- Custom Site Search Form -->
          <div class="custom_form_wrapper clearfix">  
            <form action="/{{ site_settings.content_search_results_page_path }}">
                <input class="search" type="search" name="term" placeholder="Search Articles...">
                <input class="search_btn" type="submit" value=" ">
            </form>
          </div>        
        </div>

        <!-- Slider -->
        <div class="slider_post_wrapper">
          {% set featured_posts = blog_recent_topic_posts('{{ group.id }}', 'Featured', 3) %}
          {% for featured_post in featured_posts %}
          <div class="featured_posts clearfix">

            <div class="featured_img_wrapper" style="background-image: url({{ featured_post.post_list_summary_featured_image }})">
              <a href="{{featured_post.absolute_url}}" class="featured_img_link"></a>  
            </div>  
            <div class="featured_body" onClick="window.location.href='{{featured_post.absolute_url}}'">
              <div class="featured_body_inner">
                <h2 class="featured_title">{{ featured_post.name }}</h2>    
                <div class="preview_text">{{ featured_post.post_list_content|truncatehtml(170, '...' , false) }}</div>
                <a class="read_more" href="{{featured_post.absolute_url}}">Read the article</a>
              </div>    
            </div>
          </div>
          {% endfor %}
        </div>

        <!-- Sidebar -->
        <div class="blog_sidebar">

          <!-- Sidebar CTA -->
          <div class="sidebar_cta" style="background-image: -webkit-gradient(linear, left top, left bottom, from(rgba(30,43,51, 0.9)), to(rgba(30,43,51, 0.9))), url(https://cdn2.hubspot.net/hubfs/92116/Blog%20Images/basement-cost-calculator.jpg); background-image: linear-gradient(180deg, rgba(30,43,51, 0.9), rgba(30,43,51, 0.9)), url(https://cdn2.hubspot.net/hubfs/92116/Blog%20Images/basement-cost-calculator.jpg);">
            <div class="cta_body">
              <h3>Insert your call-to-action heading in here.</h3>
              <!--HubSpot Call-to-Action Code --><span class="hs-cta-wrapper" id="hs-cta-wrapper-41f14fc9-8961-439b-aa10-c6eb39634b29"><span class="hs-cta-node hs-cta-41f14fc9-8961-439b-aa10-c6eb39634b29" id="hs-cta-41f14fc9-8961-439b-aa10-c6eb39634b29"><!--[if lte IE 8]><div id="hs-cta-ie-element"></div><![endif]--><a href="https://cta-redirect.hubspot.com/cta/redirect/92116/41f14fc9-8961-439b-aa10-c6eb39634b29" ><img class="hs-cta-img" id="hs-cta-img-41f14fc9-8961-439b-aa10-c6eb39634b29" style="border-width:0px;" src="https://no-cache.hubspot.com/cta/default/92116/41f14fc9-8961-439b-aa10-c6eb39634b29.png"  alt="Get your guide"/></a></span><script charset="utf-8" src="https://js.hscta.net/cta/current.js"></script><script type="text/javascript"> hbspt.cta.load(92116, '41f14fc9-8961-439b-aa10-c6eb39634b29', {}); </script></span><!-- end HubSpot Call-to-Action Code -->
            </div>
          </div>

          <!-- Email Subscribe Required to setup here in able to show: https://prnt.sc/tp1sj7 -->
          <div class="listing_email_subscribe">
            {% blog_subscribe "subscribe_designers_blog" select_blog='{{ group.id }}', title='Subscribe to our newsletter', response_message='Thanks for Subscribing!', label='Blog Email Subscription', overrideable=False %}
            <p>OfficeReferral uses the contact information you provide to us to contact you about our products and services. You may unsubscribe from these communications at anytime.</p>       
          </div>            
        </div>
      </div>
    </div>
    {% endif %}
  {% endif %}


  {% if request.full_url is containing "/all" %}

  <div class="split-hero-wrapper split-hero-wrapper-all">
    <div class="split-hero-top"></div>
    <div class="split-hero-bottom">
      <div class="module-max650">
        <h1>All Our Blog</h1>
      </div>
    </div>
  </div>

  {% endif %}

  <div class="main_listing {% if request.full_url is containing "/all" %}all-listing{% endif %}">
    <div class="main_listing_inner">
      <!-- Recent Posts -->
      <div class="recent_posts_wrapper">
        <div class="headting_title clearfix">
          <div class="span6">
            <p class="recent_text">Recent Articles</p>      
          </div>
          <div class="span6 cat_dropdown">
            <div class="url_slug">{{ request.path|split('/', 3)|last|lower|replace('-', ' ') }}</div>
            <div class="tag_section">
              <div class="text">Posts by topic <i class="fa fa-angle-down" aria-hidden="true"></i></div>
              {% set topics_list = blog_topics('{{ group.id }}', 250) %}            
              <ul>
                {% for topic in topics_list %}
                <li><a href="{{ blog_tag_url(group.id, topic.slug) }}">{{ topic.name }}</a></li>
                {% endfor %}
              </ul>
            </div>            
          </div>
        </div>
        {# simple_list_page indicates the "blog/all" page, which is a list of links to every blog post #}
        <div class="post_listing {% if request.full_url is containing "/all" %}post-listing-all{% endif %} clearfix {% if simple_list_page %}-simple{% endif %}">
          {% for content in contents %}
          <div class="post_item {% if request.full_url is containing "/all" %}post-item-all{% endif %}">
            <div class="inner">
              {% if not simple_list_page %}

              {% if content.post_list_summary_featured_image %}
              <div class="post__image-container">
                <a href="{{content.absolute_url}}">
                  <img src="{{ content.post_list_summary_featured_image }}" class="post__featured-image" alt="{{ content.featured_image_alt_text|escape }}">
                </a>
              </div>

              {% endif %}

              <div class="list_post_body clearfix">
                <div class="post_tags">
                  {% for topic in content.topic_list %}
                  <a href="{{ blog_tag_url(group.id, topic.slug) }}">{{ topic.name }}</a>
                  {% endfor %}                
                </div>
                <!--post summary-->
                <div class="post_header">
                  <h2><a href="{{content.absolute_url}}">{{ content.name }}</a></h2>
                </div>
                <div class="list_preview_text">
                  {{ content.post_list_content|truncatehtml(150, '...' , false) }}
                  <a class="list_preview_a" href="{{content.absolute_url}}"></a>
                </div>
                <!--
                <div class="link_wrapper">
                  <a href="{{content.absolute_url}}">Read The Article</a>
                </div>
                -->
              </div>

              {% else %}
              <!-- Start: All listing page -->

              <div class="all-blog">

                <div id="all_listing_page"></div>

                {% if request.full_url is containing "/all" %}

                {% else %}
                  {% if content.post_list_summary_featured_image %}
                  <div class="list_featured_img_wrapper">
                    <a href="{{content.absolute_url}}" title="" class="list_img_link">
                      <img src="{{ content.post_list_summary_featured_image }}" class="list_featured_img">
                    </a>
                  </div>
                  {% endif %}
                {% endif %}

                <div class="list_post_body clearfix">
                  <!--post summary-->
                  <div class="post_header">
                    <h2><a href="{{content.absolute_url}}">{{ content.name }}</a></h2>
                  </div>
                  <div class="list_preview_text">
                    {{ content.post_list_content|truncatehtml(120, '...' , false) }}
                    <a class="list_preview_a" href="{{content.absolute_url}}"></a>
                  </div>
                </div>

              </div>

              <!-- End: All listing page -->
              {% endif %}
            </div>
          </div>	

          {% endfor %}
        </div>
        <!--
        <div class="bottom_post_tags">
          <span>Topics:</span>
          {% set topics_list_bottom = blog_topics('{{ group.id }}', 250) %}
          {% for topic in topics_list_bottom %}
          <a href="{{ blog_tag_url(group.id, topic.slug) }}">{{ topic.name }}</a>
          {% endfor %}                
        </div>
        -->

        {% if request.full_url is containing "/all" %}




        {% else %}

          <div class="btn_section">
            <div class="load_more_btn btn_sec">More recent articles</div> <div class="all_articles_btn"><a class="btn_sec view-all" href="{{ group.absolute_url }}/all">View all articles</a></div>
          </div>

        {% endif %}

      </div>
    </div>
  </div>

</div>

{% require_js position="footer" %}
